/**
 * Names (and, for mechanisms, descriptions) of the template library in other languages.
 *
 * English is the source and lives with the structures (src/templates/library.json and index.json,
 * generated by templates/build_*.py). Other languages: src/i18n/templates/<code>.json, one entry
 * per template id ("mech-<id>" for mechanisms). A missing entry shows the English name.
 * `npm run check:content` and the tests report templates without a name in ca or es.
 */

interface Names {
  [id: string]: { name?: string; description?: string } | Record<string, string>;
}

const files = import.meta.glob<Names>('./templates/*.json', { eager: true, import: 'default' });

export const TEMPLATE_NAMES: Record<string, Record<string, { name?: string; description?: string }>> = Object.fromEntries(
  Object.entries(files).map(([path, data]) => {
    const { _meta, ...rest } = data;
    void _meta;
    return [path.replace(/^.*\/(.+)\.json$/, '$1'), rest as Record<string, { name?: string; description?: string }>];
  }),
);

interface Named {
  id: string;
  name: string;
  description?: string;
}

export const templateName = (e: Named, lang: string): string => TEMPLATE_NAMES[lang]?.[e.id]?.name ?? e.name;
export const templateDescription = (e: Named, lang: string): string | undefined =>
  TEMPLATE_NAMES[lang]?.[e.id]?.description ?? e.description;

/** The names of a template in every language (searched, so "benceno" finds benzene in any interface). */
export const allTemplateNames = (id: string): string[] =>
  Object.values(TEMPLATE_NAMES).map((names) => names[id]?.name).filter((n): n is string => Boolean(n));
